import{_ as t,o as a,c as o,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Neo4j context for trend captions","description":"","frontmatter":{},"headers":[],"relativePath":"feature/caption-neo4j-context/spec.md","filePath":"feature/caption-neo4j-context/spec.md"}'),n={name:"feature/caption-neo4j-context/spec.md"};function i(s,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="neo4j-context-for-trend-captions" tabindex="-1">Neo4j context for trend captions <a class="header-anchor" href="#neo4j-context-for-trend-captions" aria-label="Permalink to &quot;Neo4j context for trend captions&quot;">​</a></h1><h2 id="objective-and-user-story" tabindex="-1">Objective and user story <a class="header-anchor" href="#objective-and-user-story" aria-label="Permalink to &quot;Objective and user story&quot;">​</a></h2><p>When a creator generates three captions with a selected pipeline trend, include source-backed Neo4j observations so the model understands the people, places, organizations, products and events being discussed.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Resolve the existing trend card first; unknown/expired IDs remain rejected.</li><li>For a selected pipeline event (<code>trend:...</code>), read Neo4j by the exact ID. Do not search by approximate name or read unrelated graph neighborhoods.</li><li>Use only <code>CrawledPost - BELONGS_TO -&gt; Trend</code> and <code>CrawledPost - MENTIONS -&gt; Entity</code> evidence, with source URLs. Do not treat inferred relationships such as PROMOTED as verified endorsements.</li><li>Retrieve at most three source posts and twelve mentions. Filter records scoped to another client; format at most 3,000 characters for the prompt.</li><li>Add observations to the caption prompt alongside the existing Redis trend card and brand context. Graph names/URLs are contextual evidence, not verified prices, offers, or product claims.</li><li>Use the existing Neo4j driver, read access, a query timeout, and a three-second application deadline. On outage, missing data or test mock storage, omit graph context and keep the existing caption flow.</li><li>No new LLM call, graph write, dependency, UI control or request/response schema change. The quick generator has no selected trend ID and remains outside this change.</li></ul><h2 id="ui-api-and-error-behavior" tabindex="-1">UI, API and error behavior <a class="header-anchor" href="#ui-api-and-error-behavior" aria-label="Permalink to &quot;UI, API and error behavior&quot;">​</a></h2><p>Existing VI/EN forms, light/dark styling, authorization, credits, moderation and response payloads remain. No new locale keys or theme styles. Invalid trends return the current 404; optional graph failures are logged by exception type without exposing credentials or source content.</p><h2 id="edge-cases-and-definition-of-done" tabindex="-1">Edge cases and definition of done <a class="header-anchor" href="#edge-cases-and-definition-of-done" aria-label="Permalink to &quot;Edge cases and definition of done&quot;">​</a></h2><p>Cover absent/mismatched/private records, malformed URLs, duplicated mentions, long text, graph timeout, plain captions, and invalid trend IDs. Mocked tests must prove graph observations reach one generation call and do not disable factual checks. A configured live graph read may verify the Cypher separately without calling a paid LLM.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>Re-crawling, schema migration, storing new article text, loading every trend graph during ranking, inferred causal claims, or unifying the two frontend generators.</p>',11)])])}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
